import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const l=JSON.parse('{"title":"10.3 标准化：分级、代号与强制推荐 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"10-标准化与知识产权/03-标准化.md","filePath":"10-标准化与知识产权/03-标准化.md"}'),g={name:"10-标准化与知识产权/03-标准化.md"};function d(a,t,e,T,u,_){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_10-3-标准化-分级、代号与强制推荐-★★" tabindex="-1">10.3 标准化：分级、代号与强制推荐 ★★ <a class="header-anchor" href="#_10-3-标准化-分级、代号与强制推荐-★★" aria-label="Permalink to &quot;10.3 标准化：分级、代号与强制推荐 ★★&quot;">​</a></h1><p><strong>动机</strong>：软件要互联互通，就得有统一的标准（协议格式、编码规范、质量体系）。考试考的不是标准内容本身，而是<strong>看到代号能归类、听到说法能判断强制还是推荐</strong>。</p><h3 id="我国标准的层级与代号" tabindex="-1">我国标准的层级与代号 <a class="header-anchor" href="#我国标准的层级与代号" aria-label="Permalink to &quot;我国标准的层级与代号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>代号</th><th>举例与说明</th></tr></thead><tbody><tr><td><strong>国家标准</strong></td><td><strong>GB</strong>（强制性）、<strong>GB/T</strong>（推荐性，T = 推荐 tuī）、<strong>GB/Z</strong>（指导性技术文件，Z = 指 zhǐ）</td><td>GB 18030 强制编码标准；GB/T 19001 质量管理体系推荐标准</td></tr><tr><td><strong>行业标准</strong></td><td>各行业主管部门代号，如 <strong>SJ</strong>（电子）、<strong>YD</strong>（通信）、<strong>JB</strong>（机械）、<strong>DL</strong>（电力）、<strong>HB</strong>（航空）、<strong>GA</strong>（公安）</td><td>SJ/T 即电子行业推荐性标准</td></tr><tr><td><strong>地方标准</strong></td><td><strong>DB</strong>（DB + 省级行政区划代码，如 DB11/T 为北京地方推荐性标准）</td><td>适用于本行政区域内</td></tr><tr><td><strong>企业标准</strong></td><td><strong>Q/</strong>（企业代号）</td><td>企业内制定，要求不得低于强制性国家标准</td></tr><tr><td>团体标准</td><td>T/ + 团体代号</td><td>2018 年新《标准化法》新增的层级，了解即可</td></tr><tr><td><strong>国际标准</strong></td><td><strong>ISO</strong>（国际标准化组织）、<strong>IEC</strong>（国际电工委员会）、<strong>ITU</strong>（国际电信联盟）制定的标准，以及 ISO 确认并公布的其他国际组织标准</td><td>ISO 9001 是国际标准（我国转化为 GB/T 19001 采用）</td></tr></tbody></table><p><strong>强制性 vs 推荐性</strong>：代号里<strong>带 T（推荐）就一定不是强制性</strong>；GB（不带 T）是强制性国家标准，<strong>必须执行</strong>。按 2018 年施行的新《标准化法》，强制性标准严格限定在<strong>国家标准</strong>层面（行业、地方标准均为推荐性），旧教材里&quot;强制性行业标准/强制性行地标&quot;的说法是修订前的口径——考试认代号判推荐/强制即可，代号是绝对可靠的判别依据。</p><p><strong>标准也会过期</strong>：标准实施后要定期复审，<strong>复审周期一般不超过 5 年</strong>——技术迭代快，5 年不改的标准可能已经落伍。</p><p><strong>记忆口诀</strong>：「国行地企四层级，T 是推荐不带强制，GB 强制必须执行，复审五年不超期」。反例演示：把 GB/T 19001 判成&quot;强制性国家标准&quot;——错，带 T 即推荐性；把 ISO 9001 判成&quot;国家标准&quot;——错，它是国际标准，我国只是<strong>等同采用</strong>转化为 GB/T。</p><p><strong>团体标准代号里的 T 最容易和 GB/T 记混</strong>：两者都有字母 <strong>T</strong>，但<strong>位置</strong>不同，别当成一回事——</p><ul><li><strong>GB/T</strong>：T 在「国标代码 GB」<strong>后面</strong>，表示<strong>推荐性国家标准</strong>；</li><li><strong>T/团体代号</strong>：T 孤悬在<strong>最前面、后面带斜杠</strong>，这里的 T 是「团体 Tuántǐ」的首字母，紧跟其后的是团体代号（如 T/某协会代码）。</li></ul><p>识别特征一句话：<strong>T 在后是&quot;推荐&quot;，T 在前是&quot;团体&quot;</strong>。反例：把 T/XXX 当成&quot;推荐性标准&quot;来选——错，它是团体标准；把 GB/T 当成&quot;团体标准&quot;——同样错，它是推荐性国家标准。团体标准由<strong>社会团体</strong>（行业协会、学会等）协调相关市场主体共同制定，是 2018 年新《标准化法》新增的层级，管谁用谁自担责任，属了解即可的考点。</p><p><strong>与已学内容的联系</strong>：<a href="/ruankao/03-软件工程基础/06-软件质量与文档.html">03-软件工程基础.md</a> 讲的软件质量模型（ISO 9126）就是以&quot;ISO 国际标准&quot;形式发布的，两者代号判别口径一致。</p><p><strong>应试动作</strong>：背代号表的两列——代号 → 层级、带不带 T → 强制/推荐。认题特征：题干直接给一个标准号（GB 18030、SJ/T 10796、DB11/T、Q/ABC、ISO 9001）问归类，或给&quot;标准复审周期是几年&quot;（5 年）。纯识别题，看到 T 就选推荐。</p><hr>',13)])])}const h=o(g,[["render",d]]);export{l as __pageData,h as default};
